create type seo_content_status as enum ('draft', 'review', 'approved', 'published');

create table public.seo_locations (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  name text not null check (char_length(trim(name)) >= 2),
  province text not null check (char_length(trim(province)) >= 2),
  region_label text,
  intro_facts jsonb not null default '[]'::jsonb,
  local_characteristics jsonb not null default '[]'::jsonb,
  nearby_city_slugs jsonb not null default '[]'::jsonb,
  population_band text,
  housing_notes text,
  published boolean not null default false,
  indexable boolean not null default false,
  priority numeric(4, 2) not null default 0.5,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now())
);

create table public.seo_local_pages (
  id uuid primary key default gen_random_uuid(),
  service_slug text not null check (service_slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  subservice_slug text check (subservice_slug is null or subservice_slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  subservice_slug_key text generated always as (coalesce(subservice_slug, '')) stored,
  location_id uuid not null references public.seo_locations(id) on delete cascade,
  canonical_path text not null unique check (canonical_path ~ '^/[a-z0-9-]+/[a-z0-9-]+(/[a-z0-9-]+)?$'),
  local_intro jsonb not null default '[]'::jsonb,
  local_sections jsonb not null default '[]'::jsonb,
  faqs jsonb not null default '[]'::jsonb,
  related_local_links jsonb not null default '[]'::jsonb,
  related_service_links jsonb not null default '[]'::jsonb,
  published boolean not null default false,
  indexable boolean not null default false,
  content_status seo_content_status not null default 'draft',
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  unique(service_slug, subservice_slug_key, location_id)
);

create index seo_locations_slug_idx on public.seo_locations (slug);
create index seo_locations_published_idx on public.seo_locations (published);
create index seo_locations_indexable_idx on public.seo_locations (indexable);
create index seo_local_pages_service_slug_idx on public.seo_local_pages (service_slug);
create index seo_local_pages_subservice_slug_idx on public.seo_local_pages (subservice_slug);
create index seo_local_pages_location_id_idx on public.seo_local_pages (location_id);
create index seo_local_pages_published_idx on public.seo_local_pages (published);
create index seo_local_pages_indexable_idx on public.seo_local_pages (indexable);
create index seo_local_pages_content_status_idx on public.seo_local_pages (content_status);

create trigger set_seo_locations_updated_at
before update on public.seo_locations
for each row execute function public.set_updated_at();

create trigger set_seo_local_pages_updated_at
before update on public.seo_local_pages
for each row execute function public.set_updated_at();

alter table public.seo_locations enable row level security;
alter table public.seo_local_pages enable row level security;

create policy "published seo locations are publicly readable"
  on public.seo_locations
  for select
  using (published = true or public.is_admin());

create policy "published seo local pages are publicly readable"
  on public.seo_local_pages
  for select
  using (
    public.is_admin()
    or (
      published = true
      and indexable = true
      and content_status = 'published'
      and exists (
        select 1
        from public.seo_locations location
        where location.id = seo_local_pages.location_id
          and location.published = true
      )
    )
  );

create policy "admins manage seo locations"
  on public.seo_locations
  for all
  using (public.is_admin())
  with check (public.is_admin());

create policy "admins manage seo local pages"
  on public.seo_local_pages
  for all
  using (public.is_admin())
  with check (public.is_admin());

insert into public.seo_locations (
  slug,
  name,
  province,
  region_label,
  intro_facts,
  local_characteristics,
  nearby_city_slugs,
  population_band,
  housing_notes,
  published,
  indexable,
  priority
)
values
('amsterdam', 'Amsterdam', 'Noord-Holland', 'Randstad', '["Amsterdam combineert dichtbebouwde buurten met veel appartementen, portiekwoningen en gemengde bouwperioden.","Planning in de stad vraagt vaak extra aandacht voor bereikbaarheid, laden en lossen en werkmomenten in drukke straten."]'::jsonb, '["Bij oudere panden vraagt de combinatie van bestaande installaties en renovaties om een zorgvuldige opname vooraf.","In buurten met weinig parkeerruimte helpt het om toegang, steigeropties of liftgebruik vroeg in de aanvraag te benoemen."]'::jsonb, '["haarlem","almere","utrecht"]'::jsonb, 'zeer grootstedelijk', 'Veel appartementen, gemengde woningvoorraad en veel woningen uit verschillende bouwperioden.', true, true, 0.95),
('rotterdam', 'Rotterdam', 'Zuid-Holland', 'Randstad', '["Rotterdam heeft een mix van hoogstedelijke gebieden, wederopbouwwijken en nieuwbouwlocaties.","Bij werkzaamheden spelen logistiek, bereikbaarheid en afstemming met VvE of beheer geregeld een rol."]'::jsonb, '["In hoogbouw kunnen transportafstanden, liftcapaciteit en toegangstijden de planning beïnvloeden.","In oudere wijken is extra aandacht voor bestaande leidingen, aansluitingen en bouwkundige details vaak verstandig."]'::jsonb, '["dordrecht","den-haag","tilburg"]'::jsonb, 'zeer grootstedelijk', null, true, true, 0.94),
('den-haag', 'Den Haag', 'Zuid-Holland', 'Randstad', '["Den Haag kent veel woningen uit verschillende perioden, van oudere stadswijken tot recente uitbreidingen.","Bereikbaarheid per wijk en de combinatie van appartementen en grondgebonden woningen maken een goede intake belangrijk."]'::jsonb, '["Bij bestaande bouw is vooraf inzicht in staat van dak, leidingwerk of elektra belangrijk voor een realistische aanpak.","In dichtbebouwde straten helpt het om parkeer- en toegangssituatie expliciet mee te nemen in de aanvraag."]'::jsonb, '["rotterdam","leiden","haarlem"]'::jsonb, 'zeer grootstedelijk', null, true, true, 0.93),
('utrecht', 'Utrecht', 'Utrecht', 'Midden-Nederland', '["Utrecht combineert een compacte binnenstad met naoorlogse wijken en veel recente woningontwikkeling.","Voor planning is de balans tussen stedelijke bereikbaarheid en woonwijken met verschillende bouwjaren relevant."]'::jsonb, '["In oudere woningen kunnen verouderde aansluitingen of beperkte technische ruimtes extra voorbereiding vragen.","In nieuwere buurten ligt de nadruk vaker op uitbreiding, verduurzaming en inpassing van nieuwe installaties."]'::jsonb, '["amersfoort","amsterdam","almere"]'::jsonb, 'grootstedelijk', null, true, true, 0.92),
('eindhoven', 'Eindhoven', 'Noord-Brabant', 'Zuidoost-Brabant', '["Eindhoven heeft een combinatie van bestaande woonwijken, naoorlogse bouw en veel nieuwbouwontwikkeling.","Aanvragen profiteren van duidelijke informatie over type woning, bereikbaarheid en gewenste planning."]'::jsonb, '["Bij renovatie in oudere woningen zijn ondergrond, aansluitpunten en huidige staat vaak bepalend voor de scope.","In uitbreidingswijken draait het vaker om afwerking, upgrades en slim combineren van meerdere klussen."]'::jsonb, '["tilburg","den-bosch","breda"]'::jsonb, 'grootstedelijk', null, true, true, 0.9),
('groningen', 'Groningen', 'Groningen', 'Noord-Nederland', '["Groningen heeft een mix van binnenstedelijke woningen, jaren 30-bouw en recentere uitbreidingen.","Voor werkzaamheden helpt het om rekening te houden met wijktype, bereikbaarheid en bouwkundige staat."]'::jsonb, '["In oudere panden kunnen onderhoudsstaat en bestaande details bepalend zijn voor herstel- of renovatiekeuzes.","In appartementencomplexen is afstemming over toegang en werktijden vaak onderdeel van de voorbereiding."]'::jsonb, '["leeuwarden","zwolle","enschede"]'::jsonb, 'regionale stad', null, true, true, 0.88),
('tilburg', 'Tilburg', 'Noord-Brabant', 'Midden-Brabant', '["Tilburg heeft zowel bestaande woonwijken als nieuwbouwgebieden met uiteenlopende onderhoudsbehoeften.","Een heldere intake over woningtype en bereikbaarheid helpt om aanvragen sneller passend te maken."]'::jsonb, '["Bij oudere woningen kunnen kozijnen, daken of leidingdelen extra aandacht vragen tijdens de opname.","In nieuwere buurten spelen planning en het combineren van werkzaamheden vaak een grote rol."]'::jsonb, '["breda","eindhoven","den-bosch"]'::jsonb, 'grote stad', null, true, true, 0.86),
('almere', 'Almere', 'Flevoland', 'Flevoland', '["Almere bestaat grotendeels uit relatief jonge woonwijken met veel grondgebonden woningen.","Aanvragen draaien hier vaak om onderhoud, uitbreiding en installatiewijzigingen in moderne woningtypes."]'::jsonb, '["Bij moderne bouw ligt de nadruk vaker op comfortverbetering, verduurzaming en uitbreidingen.","Duidelijke informatie over gewenste planning en bereikbaarheid helpt bij een efficiënte opvolging."]'::jsonb, '["amsterdam","utrecht","amersfoort"]'::jsonb, 'grote stad', null, true, true, 0.82),
('breda', 'Breda', 'Noord-Brabant', 'West-Brabant', '["Breda combineert historische delen, jaren 30-wijken en uitbreidingslocaties met uiteenlopende woningtypen.","Daardoor verschillen onderhouds- en renovatievragen vaak per buurt en type woning."]'::jsonb, '["In oudere woningen vragen bestaande aansluitingen en bouwdetails vaak om een zorgvuldige beoordeling.","In recentere wijken ligt het accent vaker op planbaar onderhoud en slimme combinatie van klussen."]'::jsonb, '["tilburg","dordrecht","eindhoven"]'::jsonb, 'grote stad', null, true, true, 0.85),
('nijmegen', 'Nijmegen', 'Gelderland', 'Rijk van Nijmegen', '["Nijmegen kent een combinatie van oudere stadsdelen, naoorlogse wijken en nieuwbouwgebieden.","Voor vakwerk helpt een intake die rekening houdt met bouwperiode en bereikbaarheid."]'::jsonb, '["Bij bestaande bouw kunnen ondergrond en bestaande installaties bepalend zijn voor de aanpak.","Bij planbare klussen is duidelijke scope en fasering belangrijk voor een realistische planning."]'::jsonb, '["arnhem","apeldoorn","utrecht"]'::jsonb, 'grote stad', null, true, true, 0.84),
('arnhem', 'Arnhem', 'Gelderland', 'Arnhem-Nijmegen', '["Arnhem heeft diverse woningtypes: van oudere stadswoningen tot naoorlogse en nieuwere buurten.","Dat vraagt om maatwerk in opname, planning en uitvoering per type klus."]'::jsonb, '["Bij oudere panden kan de technische staat van bestaande voorzieningen extra voorbereiding vragen.","Voor buitenwerk en renovatie telt bereikbaarheid van locatie en materiaaltransport nadrukkelijk mee."]'::jsonb, '["nijmegen","apeldoorn","amersfoort"]'::jsonb, 'middelgrote stad', null, true, true, 0.83),
('apeldoorn', 'Apeldoorn', 'Gelderland', 'Veluwe', '["Apeldoorn heeft een brede spreiding van woonwijken met verschillende bouwjaren en woningtypen.","Voor aanvragen helpt het om huidige staat, planning en specifieke klusdoelen direct te benoemen."]'::jsonb, '["In oudere woningen kunnen onderhoudsachterstand en bestaande details de scope vergroten.","In ruim opgezette wijken is planning vaak goed voorspelbaar mits de aanvraag compleet is."]'::jsonb, '["arnhem","zwolle","amersfoort"]'::jsonb, 'middelgrote stad', null, true, true, 0.76),
('haarlem', 'Haarlem', 'Noord-Holland', 'Randstad', '["Haarlem heeft veel karakteristieke stadswijken en daarnaast nieuwere woongebieden.","Dat zorgt voor uiteenlopende onderhoudsvragen tussen oudere en recentere woningen."]'::jsonb, '["In compactere straten vraagt uitvoering soms extra afstemming over toegang en logistiek.","Bij oudere bouw is een goede technische opname belangrijk om verrassingen tijdens uitvoering te beperken."]'::jsonb, '["amsterdam","leiden","den-haag"]'::jsonb, 'middelgrote stad', null, true, true, 0.78),
('amersfoort', 'Amersfoort', 'Utrecht', 'Midden-Nederland', '["Amersfoort combineert historische delen met naoorlogse en recente uitbreidingswijken.","Hierdoor lopen klusvragen uiteen van onderhoud tot modernisering en uitbreiding."]'::jsonb, '["Bij oudere woningen kan extra aandacht nodig zijn voor bestaande aansluitingen en constructiedetails.","In nieuwere wijken draait het vaker om efficiënt plannen en combineren van werkzaamheden."]'::jsonb, '["utrecht","almere","apeldoorn"]'::jsonb, 'middelgrote stad', null, true, true, 0.77),
('zwolle', 'Zwolle', 'Overijssel', 'Regio Zwolle', '["Zwolle heeft een mix van binnenstedelijke gebieden, gezinswijken en recente nieuwbouw.","Voor goede matching helpt het om type klus en context van de woning concreet te omschrijven."]'::jsonb, '["In bestaande bouw kunnen onderhoudstoestand en bereikbaarheid sterk verschillen per wijk.","Bij planbare projecten geeft duidelijke fasering vaak sneller duidelijke vervolgstappen."]'::jsonb, '["apeldoorn","enschede","groningen"]'::jsonb, 'middelgrote stad', null, true, true, 0.75),
('leeuwarden', 'Leeuwarden', 'Friesland', 'Noord-Nederland', '["Leeuwarden kent zowel historische bebouwing als nieuwere woonwijken met verschillende onderhoudsprofielen.","Voor vakwerk is een duidelijke omschrijving van de huidige situatie en planning extra waardevol."]'::jsonb, '["Bij oudere woningen zijn staat van materiaal en bestaande aansluitingen vaak bepalend voor de aanpak.","Bij regulier onderhoud helpt het om bereikbaarheid en gewenste doorlooptijd vooraf te benoemen."]'::jsonb, '["groningen","zwolle","enschede"]'::jsonb, 'middelgrote stad', null, true, true, 0.74),
('den-bosch', 'Den Bosch', 'Noord-Brabant', 'Noordoost-Brabant', '["Den Bosch heeft een gevarieerde woningvoorraad met oudere stadsdelen en ruime uitbreidingswijken.","Dat maakt lokale context rond bouwperiode en bereikbaarheid belangrijk bij aanvragen."]'::jsonb, '["In oudere bouw kan de technische uitgangssituatie variëren, waardoor een zorgvuldige intake nodig is.","In nieuwere wijken draait het vaker om planbaar onderhoud en functionele upgrades."]'::jsonb, '["eindhoven","tilburg","utrecht"]'::jsonb, 'middelgrote stad', null, true, true, 0.79),
('enschede', 'Enschede', 'Overijssel', 'Twente', '["Enschede combineert oudere wijken met moderne woongebieden en uiteenlopende woningtypes.","Voor lokale aanvragen helpt een heldere omschrijving van situatie, planning en gewenste oplossing."]'::jsonb, '["Bij bestaande woningen kunnen onderhoudsstatus en eerdere aanpassingen invloed hebben op de uitvoering.","Bij grotere klussen geeft een gefaseerde aanpak vaak meer voorspelbaarheid in planning en kostenfactoren."]'::jsonb, '["zwolle","arnhem","nijmegen"]'::jsonb, 'middelgrote stad', null, true, true, 0.73),
('leiden', 'Leiden', 'Zuid-Holland', 'Randstad', '["Leiden heeft een combinatie van historische kern, bestaande woonwijken en nieuwere ontwikkelgebieden.","Daardoor verschillen klusaanpakken regelmatig tussen binnenstad, schilwijken en nieuwe buurten."]'::jsonb, '["In oudere bebouwing kunnen bestaande details en bereikbaarheid bepalend zijn voor de werkvoorbereiding.","In moderner vastgoed ligt de focus vaak op efficiënt onderhoud en technische verbeteringen."]'::jsonb, '["den-haag","haarlem","rotterdam"]'::jsonb, 'middelgrote stad', null, true, true, 0.72),
('dordrecht', 'Dordrecht', 'Zuid-Holland', 'Drechtsteden', '["Dordrecht kent historische buurten, naoorlogse wijken en nieuwere woongebieden.","Voor een passende vakmanselectie is lokale context over woningtype en staat van belang."]'::jsonb, '["Bij oudere woningen kunnen onderhoudsachterstand en bestaande aansluitingen extra aandacht vragen.","Bij planbare verbeteringen helpt het om gewenste planning en prioriteiten in de aanvraag te specificeren."]'::jsonb, '["rotterdam","breda","tilburg"]'::jsonb, 'middelgrote stad', null, true, true, 0.71)
on conflict (slug)
do update set
  name = excluded.name,
  province = excluded.province,
  region_label = excluded.region_label,
  intro_facts = excluded.intro_facts,
  local_characteristics = excluded.local_characteristics,
  nearby_city_slugs = excluded.nearby_city_slugs,
  population_band = excluded.population_band,
  housing_notes = excluded.housing_notes,
  published = excluded.published,
  indexable = excluded.indexable,
  priority = excluded.priority,
  updated_at = timezone('utc', now());

insert into public.seo_local_pages (
  service_slug,
  subservice_slug,
  location_id,
  canonical_path,
  local_intro,
  local_sections,
  faqs,
  related_local_links,
  related_service_links,
  published,
  indexable,
  content_status
)
select
  source.service_slug,
  source.subservice_slug,
  location.id,
  source.canonical_path,
  source.local_intro,
  source.local_sections,
  source.faqs,
  source.related_local_links,
  source.related_service_links,
  source.published,
  source.indexable,
  source.content_status::seo_content_status
from (
  values
('dakdekker', null, 'amsterdam', '/dakdekker/amsterdam', '["Zoek je een dakdekker in Amsterdam? VakConnect helpt je om je aanvraag inhoudelijk scherp neer te zetten, zodat je sneller bij een passende vakman uitkomt.","Amsterdam combineert dichtbebouwde buurten met veel appartementen, portiekwoningen en gemengde bouwperioden. Dakwerk in deze regio varieert van lekkageherstel en onderhoud tot renovatie van complete dakdelen."]'::jsonb, '[{"heading":"Welke klussen zijn vaak relevant voor Dakdekker in Amsterdam","paragraphs":["Dakwerk in deze regio varieert van lekkageherstel en onderhoud tot renovatie van complete dakdelen. In Amsterdam helpt het om vooraf te specificeren of het om onderhoud, herstel of bredere renovatie gaat.","Met een complete intake kan een vakman sneller bepalen welke aanpak het beste past bij jouw situatie in Amsterdam."],"bullets":["duidelijke probleemomschrijving of klusdoel","foto’s van relevante onderdelen","gewenste planning en eventuele urgentie","toegangssituatie en praktische randvoorwaarden"]},{"heading":"Woning- en bouwcontext in Amsterdam","paragraphs":["Amsterdam combineert dichtbebouwde buurten met veel appartementen, portiekwoningen en gemengde bouwperioden. Planning in de stad vraagt vaak extra aandacht voor bereikbaarheid, laden en lossen en werkmomenten in drukke straten.","Bij oudere woningen vragen aansluitingen, afwatering en staat van bestaande daklagen vaak extra aandacht. Bij oudere panden vraagt de combinatie van bestaande installaties en renovaties om een zorgvuldige opname vooraf."]},{"heading":"Bereikbaarheid en planning in Amsterdam","paragraphs":["In buurten met weinig parkeerruimte helpt het om toegang, steigeropties of liftgebruik vroeg in de aanvraag te benoemen. Bij woningen in drukke of compacte straten is een goede inschatting van bereikbaarheid en werkhoogte essentieel.","Door planning, toegang en gewenste uitvoeringsperiode vooraf te delen, wordt de intake inhoudelijk sterker en beter vergelijkbaar."],"type":"info"},{"heading":"Prijsfactoren zonder vaste lokale aannames","paragraphs":["De kosten hangen af van de technische situatie, benodigde werkzaamheden en gekozen materialen, niet van standaardbedragen per stad.","Via VakConnect krijg je ruimte om je situatie in Amsterdam zorgvuldig te beschrijven, zodat een vakman op inhoud kan reageren."],"bullets":["Daktype en bereikbaarheid van het werkvlak","Benodigde herstelomvang en staat van bestaande details","Materiaalkeuze en afwerking rond randen, goten en doorvoeren","Combinatie met isolatie of aanvullende dakwerkzaamheden"]},{"heading":"Hoe VakConnect lokaal matcht in Amsterdam","paragraphs":["VakConnect voert het werk niet zelf uit, maar koppelt je aanvraag aan passende vakmensen voor dakdekker in amsterdam.","De match gebeurt op basis van dienst, inhoud van je aanvraag en werkgebied, waarna je de uitvoering direct met de vakman afstemt."]}]'::jsonb, '[{"question":"Hoe vind ik via VakConnect een dakdekker in Amsterdam?","answer":"Start met een duidelijke aanvraag op VakConnect. Beschrijf de situatie, voeg relevante details toe en kies de gewenste planning zodat je gekoppeld wordt aan passende vakmensen in of rond Amsterdam."},{"question":"Kan ik spoed aangeven bij mijn aanvraag?","answer":"Ja, je kunt urgentie benoemen in je aanvraag. De uiteindelijke beschikbaarheid en responstijd bespreek je daarna rechtstreeks met de vakman die je aanvraag oppakt."},{"question":"Welke informatie helpt voor een goede intake in Amsterdam?","answer":"Noem altijd de huidige situatie, gewenste oplossing, bereikbaarheid en eventuele foto’s. Hoe concreter de informatie, hoe beter een vakman de opdracht inhoudelijk kan beoordelen."},{"question":"Werkt VakConnect met vakmensen uit de regio?","answer":"VakConnect koppelt aanvragen aan passende vakmensen op basis van dienst en werkgebied. Dat kan een specialist uit de stad zelf zijn of uit een omliggende plaats."},{"question":"Kan ik ook een specialist uit een nabijgelegen plaats ontvangen?","answer":"Ja. Als dat inhoudelijk of qua planning beter past, kan je aanvraag ook uitkomen bij een vakman uit de omliggende regio."}]'::jsonb, '["haarlem","almere","utrecht"]'::jsonb, '[{"href":"/dakdekker","title":"Dakdekker overzicht","description":"Bekijk de hoofdpagina voor dakdekker en algemene aanpakkeuzes."},{"href":"/dakdekker/daklekkage","title":"Daklekkage","description":"Bekijk daklekkage als specifieke vervolgroute."},{"href":"/dakdekker/dakrenovatie","title":"Dakrenovatie","description":"Bekijk dakrenovatie als specifieke vervolgroute."},{"href":"/aanvraag","title":"Aanvraag starten","description":"Plaats direct je klusaanvraag met details over locatie en planning."}]'::jsonb, true, true, 'published'),
('dakdekker', null, 'rotterdam', '/dakdekker/rotterdam', '["Zoek je een dakdekker in Rotterdam? VakConnect helpt je om je aanvraag inhoudelijk scherp neer te zetten, zodat je sneller bij een passende vakman uitkomt.","Rotterdam heeft een mix van hoogstedelijke gebieden, wederopbouwwijken en nieuwbouwlocaties. Dakwerk in deze regio varieert van lekkageherstel en onderhoud tot renovatie van complete dakdelen."]'::jsonb, '[{"heading":"Welke klussen zijn vaak relevant voor Dakdekker in Rotterdam","paragraphs":["Dakwerk in deze regio varieert van lekkageherstel en onderhoud tot renovatie van complete dakdelen. In Rotterdam helpt het om vooraf te specificeren of het om onderhoud, herstel of bredere renovatie gaat.","Met een complete intake kan een vakman sneller bepalen welke aanpak het beste past bij jouw situatie in Rotterdam."],"bullets":["duidelijke probleemomschrijving of klusdoel","foto’s van relevante onderdelen","gewenste planning en eventuele urgentie","toegangssituatie en praktische randvoorwaarden"]},{"heading":"Woning- en bouwcontext in Rotterdam","paragraphs":["Rotterdam heeft een mix van hoogstedelijke gebieden, wederopbouwwijken en nieuwbouwlocaties. Bij werkzaamheden spelen logistiek, bereikbaarheid en afstemming met VvE of beheer geregeld een rol.","Bij oudere woningen vragen aansluitingen, afwatering en staat van bestaande daklagen vaak extra aandacht. In hoogbouw kunnen transportafstanden, liftcapaciteit en toegangstijden de planning beïnvloeden."]},{"heading":"Bereikbaarheid en planning in Rotterdam","paragraphs":["In oudere wijken is extra aandacht voor bestaande leidingen, aansluitingen en bouwkundige details vaak verstandig. Bij woningen in drukke of compacte straten is een goede inschatting van bereikbaarheid en werkhoogte essentieel.","Door planning, toegang en gewenste uitvoeringsperiode vooraf te delen, wordt de intake inhoudelijk sterker en beter vergelijkbaar."],"type":"info"},{"heading":"Prijsfactoren zonder vaste lokale aannames","paragraphs":["De kosten hangen af van de technische situatie, benodigde werkzaamheden en gekozen materialen, niet van standaardbedragen per stad.","Via VakConnect krijg je ruimte om je situatie in Rotterdam zorgvuldig te beschrijven, zodat een vakman op inhoud kan reageren."],"bullets":["Daktype en bereikbaarheid van het werkvlak","Benodigde herstelomvang en staat van bestaande details","Materiaalkeuze en afwerking rond randen, goten en doorvoeren","Combinatie met isolatie of aanvullende dakwerkzaamheden"]},{"heading":"Hoe VakConnect lokaal matcht in Rotterdam","paragraphs":["VakConnect voert het werk niet zelf uit, maar koppelt je aanvraag aan passende vakmensen voor dakdekker in rotterdam.","De match gebeurt op basis van dienst, inhoud van je aanvraag en werkgebied, waarna je de uitvoering direct met de vakman afstemt."]}]'::jsonb, '[{"question":"Hoe vind ik via VakConnect een dakdekker in Rotterdam?","answer":"Start met een duidelijke aanvraag op VakConnect. Beschrijf de situatie, voeg relevante details toe en kies de gewenste planning zodat je gekoppeld wordt aan passende vakmensen in of rond Rotterdam."},{"question":"Kan ik spoed aangeven bij mijn aanvraag?","answer":"Ja, je kunt urgentie benoemen in je aanvraag. De uiteindelijke beschikbaarheid en responstijd bespreek je daarna rechtstreeks met de vakman die je aanvraag oppakt."},{"question":"Welke informatie helpt voor een goede intake in Rotterdam?","answer":"Noem altijd de huidige situatie, gewenste oplossing, bereikbaarheid en eventuele foto’s. Hoe concreter de informatie, hoe beter een vakman de opdracht inhoudelijk kan beoordelen."},{"question":"Werkt VakConnect met vakmensen uit de regio?","answer":"VakConnect koppelt aanvragen aan passende vakmensen op basis van dienst en werkgebied. Dat kan een specialist uit de stad zelf zijn of uit een omliggende plaats."},{"question":"Kan ik ook een specialist uit een nabijgelegen plaats ontvangen?","answer":"Ja. Als dat inhoudelijk of qua planning beter past, kan je aanvraag ook uitkomen bij een vakman uit de omliggende regio."}]'::jsonb, '["dordrecht","den-haag","tilburg"]'::jsonb, '[{"href":"/dakdekker","title":"Dakdekker overzicht","description":"Bekijk de hoofdpagina voor dakdekker en algemene aanpakkeuzes."},{"href":"/dakdekker/daklekkage","title":"Daklekkage","description":"Bekijk daklekkage als specifieke vervolgroute."},{"href":"/dakdekker/dakrenovatie","title":"Dakrenovatie","description":"Bekijk dakrenovatie als specifieke vervolgroute."},{"href":"/aanvraag","title":"Aanvraag starten","description":"Plaats direct je klusaanvraag met details over locatie en planning."}]'::jsonb, true, true, 'published'),
